arguments.command:
mkdir -p /workspace/submission/infra && cd /workspace/submission/infra && cat > main.tf <<'EOF'
terraform {
  required_version = ">= 1.5.0"
  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 6.0"
    }
  }
}

variable "config_file" {
  description = "Path to the runtime configuration JSON"
  type        = string
  default     = "/workspace/config/config.json"
}

locals {
  config   = jsondecode(file(var.config_file))
  prefix   = local.config.resource_prefix
  region   = local.config.region
  endpoint = local.config.aws_endpoint_url

  tags = {
    ClearLedgerDeployment = local.prefix
  }

  azs = ["us-east-1a", "us-east-1b"]

  api_log_group       = "/clearledger/${local.prefix}/api"
  projector_log_group = "/clearledger/${local.prefix}/projector"
  relay_log_group     = "/clearledger/${local.prefix}/outbox-relay"
  archiver_log_group  = "/clearledger/${local.prefix}/audit-archiver"

  database_url = "postgres://${local.config.db_username}:${local.config.db_password}@${aws_db_instance.main.address}:${aws_db_instance.main.port}/${local.config.db_name}"
  valkey_url   = "redis://${local.valkey_endpoint}:${local.valkey_port}"

  # Endpoint as seen from inside containers / lambdas.
  runtime_endpoint = local.endpoint
}

provider "aws" {
  region                      = local.region
  access_key                  = "test"
  secret_key                  = "test"
  skip_credentials_validation = true
  skip_metadata_api_check     = true
  skip_requesting_account_id  = true
  skip_region_validation      = true
  s3_use_path_style           = true

  endpoints {
    ec2            = local.endpoint
    elbv2          = local.endpoint
    elb            = local.endpoint
    ecs            = local.endpoint
    rds            = local.endpoint
    elasticache    = local.endpoint
    s3             = local.endpoint
    sqs            = local.endpoint
    lambda         = local.endpoint
    scheduler      = local.endpoint
    cognitoidp     = local.endpoint
    iam            = local.endpoint
    kms            = local.endpoint
    cloudwatchlogs = local.endpoint
    dynamodb       = local.endpoint
    sts            = local.endpoint
    ecr            = local.endpoint
  }

  default_tags {
    tags = local.tags
  }
}

data "aws_caller_identity" "current" {}

locals {
  account_id = data.aws_caller_identity.current.account_id
}
EOF
cat > network.tf <<'EOF'
resource "aws_vpc" "main" {
  cidr_block           = "10.20.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags                 = merge(local.tags, { Name = "${local.prefix}-vpc" })
}

resource "aws_internet_gateway" "main" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-igw" })
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = "10.20.${count.index}.0/24"
  map_public_ip_on_launch = true
  tags                    = merge(local.tags, { Name = "${local.prefix}-public-${local.azs[count.index]}", Tier = "public" })
}

resource "aws_subnet" "private" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  availability_zone       = local.azs[count.index]
  cidr_block              = "10.20.${10 + count.index}.0/24"
  map_public_ip_on_launch = false
  tags                    = merge(local.tags, { Name = "${local.prefix}-private-${local.azs[count.index]}", Tier = "private" })
}

resource "aws_route_table" "public" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-public-rt" })
}

resource "aws_route" "public_internet" {
  route_table_id         = aws_route_table.public.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.main.id
}

resource "aws_route_table" "private" {
  vpc_id = aws_vpc.main.id
  tags   = merge(local.tags, { Name = "${local.prefix}-private-rt" })
}

resource "aws_route_table_association" "public" {
  count          = 2
  subnet_id      = aws_subnet.public[count.index].id
  route_table_id = aws_route_table.public.id
}

resource "aws_route_table_association" "private" {
  count          = 2
  subnet_id      = aws_subnet.private[count.index].id
  route_table_id = aws_route_table.private.id
}

# ---------------------------------------------------------------------------
# Security groups. Rules are inline so that Terraform owns the complete rule
# set and removes out-of-band rules (e.g. egress added to rds/valkey) on apply.
# ---------------------------------------------------------------------------
resource "aws_security_group" "alb" {
  name        = "${local.prefix}-alb"
  description = "ClearLedger ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    description = "HTTP from anywhere"
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "Forward to API tasks inside the VPC"
    from_port   = 8080
    to_port     = 8080
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-alb" })
}

resource "aws_security_group" "ecs" {
  name        = "${local.prefix}-ecs"
  description = "ClearLedger API tasks"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "API port from ALB only"
    from_port       = 8080
    to_port         = 8080
    protocol        = "tcp"
    security_groups = [aws_security_group.alb.id]
  }

  egress {
    description = "AWS control plane and HTTPS"
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "AWS control plane endpoint"
    from_port   = 4566
    to_port     = 4566
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    description = "PostgreSQL"
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  egress {
    description = "Valkey"
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main.cidr_block]
  }

  tags = merge(local.tags, { Name = "${local.prefix}-ecs" })
}

resource "aws_security_group" "rds" {
  name        = "${local.prefix}-rds"
  description = "ClearLedger PostgreSQL"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "PostgreSQL from API tasks"
    from_port       = 5432
    to_port         = 5432
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-rds" })
}

resource "aws_security_group" "valkey" {
  name        = "${local.prefix}-valkey"
  description = "ClearLedger Valkey"
  vpc_id      = aws_vpc.main.id

  ingress {
    description     = "Valkey from API tasks"
    from_port       = 6379
    to_port         = 6379
    protocol        = "tcp"
    security_groups = [aws_security_group.ecs.id]
  }

  egress = []

  tags = merge(local.tags, { Name = "${local.prefix}-valkey" })
}
EOF
cat > kms.tf <<'EOF'
locals {
  kms_keys = toset(["database", "messaging", "projection", "audit"])
}

resource "aws_kms_key" "this" {
  for_each                = local.kms_keys
  description             = "ClearLedger ${each.key} key (${local.prefix})"
  enable_key_rotation     = true
  deletion_window_in_days = 10
  tags                    = merge(local.tags, { Name = "${local.prefix}-${each.key}" })
}

resource "aws_kms_alias" "this" {
  for_each      = local.kms_keys
  name          = "alias/${local.prefix}-${each.key}"
  target_key_id = aws_kms_key.this[each.key].key_id
}
EOF
cat > logs.tf <<'EOF'
resource "aws_cloudwatch_log_group" "api" {
  name              = local.api_log_group
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "projector" {
  name              = local.projector_log_group
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "relay" {
  name              = local.relay_log_group
  retention_in_days = 14
  tags              = local.tags
}

resource "aws_cloudwatch_log_group" "archiver" {
  name              = local.archiver_log_group
  retention_in_days = 14
  tags              = local.tags
}
EOF

cd /workspace/submission/infra && cat > data.tf <<'EOF'
# ---------------------------------------------------------------------------
# RDS PostgreSQL
# ---------------------------------------------------------------------------
resource "aws_db_subnet_group" "main" {
  name       = "${local.prefix}-db"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.prefix}-db" })
}

resource "aws_db_instance" "main" {
  identifier             = "${local.prefix}-db"
  engine                 = "postgres"
  engine_version         = "16.3"
  instance_class         = "db.t4g.micro"
  allocated_storage      = 20
  db_name                = local.config.db_name
  username               = local.config.db_username
  password               = local.config.db_password
  storage_encrypted      = true
  kms_key_id             = aws_kms_key.this["database"].arn
  publicly_accessible    = false
  skip_final_snapshot    = true
  deletion_protection    = false
  apply_immediately      = true
  db_subnet_group_name   = aws_db_subnet_group.main.name
  vpc_security_group_ids = [aws_security_group.rds.id]
  tags                   = merge(local.tags, { Name = "${local.prefix}-db" })

  lifecycle {
    # Never replace the database (and lose committed data) because of
    # non-functional attribute drift.
    ignore_changes = [engine_version, password, kms_key_id, db_name, username]
  }
}

# ---------------------------------------------------------------------------
# DynamoDB projection table
# ---------------------------------------------------------------------------
resource "aws_dynamodb_table" "projections" {
  name         = "${local.prefix}-projections"
  billing_mode = "PAY_PER_REQUEST"
  hash_key     = "PK"
  range_key    = "SK"

  attribute {
    name = "PK"
    type = "S"
  }
  attribute {
    name = "SK"
    type = "S"
  }
  attribute {
    name = "GSI1PK"
    type = "S"
  }
  attribute {
    name = "GSI1SK"
    type = "S"
  }

  global_secondary_index {
    name            = "AccountIndex"
    hash_key        = "GSI1PK"
    range_key       = "GSI1SK"
    projection_type = "ALL"
  }

  point_in_time_recovery {
    enabled = true
  }

  server_side_encryption {
    enabled     = true
    kms_key_arn = aws_kms_key.this["projection"].arn
  }

  tags = merge(local.tags, { Name = "${local.prefix}-projections" })
}

# ---------------------------------------------------------------------------
# ElastiCache for Valkey
# ---------------------------------------------------------------------------
resource "aws_elasticache_subnet_group" "main" {
  name       = "${local.prefix}-valkey"
  subnet_ids = aws_subnet.private[*].id
  tags       = merge(local.tags, { Name = "${local.prefix}-valkey" })
}

resource "aws_elasticache_replication_group" "valkey" {
  replication_group_id = "${local.prefix}-valkey"
  description          = "ClearLedger projection cache (${local.prefix})"
  engine               = "valkey"
  engine_version       = "8.0"
  node_type            = "cache.t4g.micro"
  num_cache_clusters   = 1
  port                 = 6379
  subnet_group_name    = aws_elasticache_subnet_group.main.name
  security_group_ids   = [aws_security_group.valkey.id]
  apply_immediately    = true
  tags                 = merge(local.tags, { Name = "${local.prefix}-valkey" })
}

locals {
  valkey_endpoint = coalesce(
    try(aws_elasticache_replication_group.valkey.primary_endpoint_address, null),
    try(aws_elasticache_replication_group.valkey.configuration_endpoint_address, null),
    try(aws_elasticache_replication_group.valkey.reader_endpoint_address, null),
  )
  valkey_port = aws_elasticache_replication_group.valkey.port
}

# ---------------------------------------------------------------------------
# S3 audit archive
# ---------------------------------------------------------------------------
resource "aws_s3_bucket" "audit" {
  bucket        = "${local.prefix}-audit"
  force_destroy = true
  tags          = merge(local.tags, { Name = "${local.prefix}-audit" })
}

resource "aws_s3_bucket_versioning" "audit" {
  bucket = aws_s3_bucket.audit.id
  versioning_configuration {
    status = "Enabled"
  }
}

resource "aws_s3_bucket_server_side_encryption_configuration" "audit" {
  bucket = aws_s3_bucket.audit.id
  rule {
    apply_server_side_encryption_by_default {
      sse_algorithm     = "aws:kms"
      kms_master_key_id = aws_kms_key.this["audit"].arn
    }
  }
}

resource "aws_s3_bucket_public_access_block" "audit" {
  bucket                  = aws_s3_bucket.audit.id
  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

# ---------------------------------------------------------------------------
# SQS main queue + DLQ
# ---------------------------------------------------------------------------
resource "aws_sqs_queue" "dlq" {
  name                      = "${local.prefix}-events-dlq"
  kms_master_key_id         = aws_kms_key.this["messaging"].arn
  message_retention_seconds = 1209600
  tags                      = merge(local.tags, { Name = "${local.prefix}-events-dlq" })
}

resource "aws_sqs_queue" "main" {
  name                       = "${local.prefix}-events"
  kms_master_key_id          = aws_kms_key.this["messaging"].arn
  visibility_timeout_seconds = 3
  receive_wait_time_seconds  = 2
  message_retention_seconds  = 172800
  redrive_policy = jsonencode({
    deadLetterTargetArn = aws_sqs_queue.dlq.arn
    maxReceiveCount     = 4
  })
  tags = merge(local.tags, { Name = "${local.prefix}-events" })
}
EOF
terraform init -input=false 2>&1 | tail -5

cd /workspace/submission/infra && cat > iam.tf <<'EOF'
# ---------------------------------------------------------------------------
# IAM: six dedicated roles, each with least-privilege Allow statements and
# explicit Deny guardrails. No wildcard actions or wildcard resources in Allow.
# ---------------------------------------------------------------------------
locals {
  q_arn      = aws_sqs_queue.main.arn
  dlq_arn    = aws_sqs_queue.dlq.arn
  table_arn  = aws_dynamodb_table.projections.arn
  index_arn  = "${aws_dynamodb_table.projections.arn}/index/AccountIndex"
  bucket_arn = aws_s3_bucket.audit.arn
  bucket_all = "${aws_s3_bucket.audit.arn}/*"
  bucket_ao  = "${aws_s3_bucket.audit.arn}/ledger-audit/*"

  kms_arn = { for k, v in aws_kms_key.this : k => v.arn }

  # Each log group is addressed by its own ARN plus its log-stream ARNs.
  lg = {
    api       = [aws_cloudwatch_log_group.api.arn, "${aws_cloudwatch_log_group.api.arn}:*"]
    projector = [aws_cloudwatch_log_group.projector.arn, "${aws_cloudwatch_log_group.projector.arn}:*"]
    relay     = [aws_cloudwatch_log_group.relay.arn, "${aws_cloudwatch_log_group.relay.arn}:*"]
    archiver  = [aws_cloudwatch_log_group.archiver.arn, "${aws_cloudwatch_log_group.archiver.arn}:*"]
  }

  logs_write      = ["logs:CreateLogStream", "logs:PutLogEvents", "logs:DescribeLogStreams"]
  logs_deny       = ["logs:CreateLogStream", "logs:PutLogEvents"]
  kms_use         = ["kms:Decrypt", "kms:GenerateDataKey", "kms:DescribeKey"]
  kms_deny        = ["kms:Decrypt", "kms:GenerateDataKey"]
  ddb_all_deny    = ["dynamodb:GetItem", "dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:Query"]
  s3_all_deny     = ["s3:GetObject", "s3:PutObject", "s3:DeleteObject", "s3:ListBucket"]
  sqs_all_deny    = ["sqs:SendMessage", "sqs:ReceiveMessage", "sqs:DeleteMessage"]
  ddb_resources   = [local.table_arn, local.index_arn]
  bucket_all_arns = [local.bucket_arn, local.bucket_all]
}

data "aws_iam_policy_document" "trust_ecs" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["ecs-tasks.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "trust_lambda" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["lambda.amazonaws.com"]
    }
  }
}

data "aws_iam_policy_document" "trust_scheduler" {
  statement {
    effect  = "Allow"
    actions = ["sts:AssumeRole"]
    principals {
      type        = "Service"
      identifiers = ["scheduler.amazonaws.com"]
    }
  }
}

resource "aws_iam_role" "ecs_execution" {
  name               = "${local.prefix}-ecs-execution"
  assume_role_policy = data.aws_iam_policy_document.trust_ecs.json
  tags               = local.tags
}

resource "aws_iam_role" "ecs_task" {
  name               = "${local.prefix}-ecs-task"
  assume_role_policy = data.aws_iam_policy_document.trust_ecs.json
  tags               = local.tags
}

resource "aws_iam_role" "projector" {
  name               = "${local.prefix}-projector"
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = local.tags
}

resource "aws_iam_role" "relay" {
  name               = "${local.prefix}-relay"
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = local.tags
}

resource "aws_iam_role" "archiver" {
  name               = "${local.prefix}-archiver"
  assume_role_policy = data.aws_iam_policy_document.trust_lambda.json
  tags               = local.tags
}

resource "aws_iam_role" "scheduler" {
  name               = "${local.prefix}-scheduler"
  assume_role_policy = data.aws_iam_policy_document.trust_scheduler.json
  tags               = local.tags
}

# 1. ECS execution role: only writes to the API log group.
resource "aws_iam_role_policy" "ecs_execution" {
  name = "${local.prefix}-ecs-execution"
  role = aws_iam_role.ecs_execution.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ApiLogsWrite"
        Effect   = "Allow"
        Action   = local.logs_write
        Resource = local.lg.api
      },
      {
        Sid      = "DenySqs"
        Effect   = "Deny"
        Action   = local.sqs_all_deny
        Resource = [local.q_arn, local.dlq_arn]
      },
      {
        Sid      = "DenyDynamoDb"
        Effect   = "Deny"
        Action   = local.ddb_all_deny
        Resource = local.ddb_resources
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = local.s3_all_deny
        Resource = local.bucket_all_arns
      },
      {
        Sid      = "DenyKms"
        Effect   = "Deny"
        Action   = local.kms_deny
        Resource = [for k in ["database", "messaging", "projection", "audit"] : local.kms_arn[k]]
      },
      {
        Sid      = "DenyOtherLogGroups"
        Effect   = "Deny"
        Action   = local.logs_deny
        Resource = concat(local.lg.projector, local.lg.relay, local.lg.archiver)
      },
    ]
  })
}

# 2. ECS task role (API): publish to SQS, read projections, own log group.
resource "aws_iam_role_policy" "ecs_task" {
  name = "${local.prefix}-ecs-task"
  role = aws_iam_role.ecs_task.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "PublishMainQueue"
        Effect   = "Allow"
        Action   = ["sqs:SendMessage", "sqs:GetQueueAttributes", "sqs:GetQueueUrl"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "ReadProjections"
        Effect   = "Allow"
        Action   = ["dynamodb:GetItem", "dynamodb:Query", "dynamodb:DescribeTable"]
        Resource = local.ddb_resources
      },
      {
        Sid      = "UseKeys"
        Effect   = "Allow"
        Action   = local.kms_use
        Resource = [local.kms_arn["messaging"], local.kms_arn["projection"]]
      },
      {
        Sid      = "ApiLogsWrite"
        Effect   = "Allow"
        Action   = local.logs_write
        Resource = local.lg.api
      },
      {
        Sid      = "DenySqsConsume"
        Effect   = "Deny"
        Action   = ["sqs:ReceiveMessage", "sqs:DeleteMessage"]
        Resource = [local.q_arn]
      },
      {
        Sid      = "DenyDlqAccess"
        Effect   = "Deny"
        Action   = local.sqs_all_deny
        Resource = [local.dlq_arn]
      },
      {
        Sid      = "DenyDynamoDbMutation"
        Effect   = "Deny"
        Action   = ["dynamodb:PutItem", "dynamodb:UpdateItem", "dynamodb:DeleteItem", "dynamodb:DeleteTable"]
        Resource = [local.table_arn]
      },
      {
        Sid      = "DenyS3"
        Effect   = "Deny"
        Action   = local.s3_all_deny
        Resource = local.bucket_all_arns
      },
      {
        Sid      = "DenyForeignKms"
        Effect   = "Deny"
        Action   = local.kms_deny
        Resource = [local.kms_arn["database"], local.kms_arn["audit"]]
      },
      {
        Sid      = "DenyOtherLogGroups"
        Effect   = "Deny"
        Action   = local.logs_deny
        Resource = concat(local.lg.projector, local.lg.relay, local.lg.archiver)
      },
    ]
  })
}

# 3. Projector Lambda role.
resource "aws_iam_role_policy" "projector" {
  name = "${local.prefix}-projector"
  role = aws_iam_role.projector.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid      = "ConsumeMainQueue"
